       process.env.CI !== '******' ||
       process.env.GITHUB_ACTIONS !== '******' ||
       !isAbsolute(options.acceptanceAssetDirectory)
     ) {
       throw new Error(
         'Local acceptance assets require an absolute path on GitHub Actions.',
