    VERSION: ${{ steps.validate.outputs.version }}
  run: |
    gh workflow run release.yml \
      --repo "$GITHUB_REPOSITORY" \
      --ref "$DEFAULT_BRANCH" \
      -f bump=current \
      -f source_sha="$MERGE_SHA"
    echo "Dispatched hvir $VERSION from $MERGE_SHA" >> "$GITHUB_STEP_SUMMARY"

